solution:
import re

def redact(line):
    return re.sub(r"password=\S+", "password=****", line)

alt:
def redact(line):
    words = line.split(" ")
    out = []
    for w in words:
        out.append("password=****" if w.startswith("password=") else w)
    return " ".join(out)
